def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

count = 0
for num in range(10, 100):
    if is_prime(num):
        digit_sum = (num // 10) + (num % 10)
        if digit_sum == 8:
            count += 1

print(count)
