}

# All permutations of visiting the other three points once
from itertools import permutations

# Function to calculate total distance for a route
def calculate_distance(route, distances):
    total = 0
    for i in range(len(route) - 1):
        total += distances[route[i]][route[i+1]]
    return total

# List of all possible starting points
starting_points = ['A', 'B', 'C', 'D']

# Find the shortest distance
shortest_distance = float('inf')

for start in starting_points:
    # Generate all permutations of the other three points
    for perm in permutations(['A', 'B', 'C', 'D']):
        if perm[0] == start:
            # Calculate the total distance for this route
            distance = calculate_distance(perm, distances)
            if distance < shortest_distance:
                shortest_distance = distance

shortest_distance
