# Step 1: Find all positive divisors of 500
def get_divisors(n):
    divisors = []
    for i in range(1, n + 1):
        if n % i == 0:
            divisors.append(i)
    return divisors

# Step 2: Calculate the sum of the divisors
def sum_of_divisors(n):
    return sum(get_divisors(n))

# Step 3: Find the prime divisors of the sum
def prime_divisors(n):
    prime_factors = set()
    i = 2
    while i * i <= n:
        if n % i == 0:
            prime_factors.add(i)
            while n % i == 0:
                n //= i
        i += 1
    if n > 1:
        prime_factors.add(n)
    return prime_factors

# Step 4: Compute the sum of the distinct prime divisors of A
A = sum_of_divisors(500)
prime_divisors_of_A = prime_divisors(A)
sum_of_prime_divisors = sum(prime_divisors_of_A)

print(sum_of_prime_divisors)
```

